\begin{itemchoice}
			\itemch $\cos\alpha=\cos\left(\dfrac{\pi}{3}+k2\pi\right)=\cos\left(\dfrac{\pi}{3}\right)=\dfrac{1}{2}$.
			\itemch $\tan\alpha=\tan\left(\dfrac{\pi}{3}+k2\pi\right)=\tan\left(\dfrac{\pi}{3}\right)=\sqrt{3}$.
			\itemch $\sin\alpha=\sin\left(\dfrac{\pi}{3}+k2\pi\right)=\sin\left(\dfrac{\pi}{3}\right)=\dfrac{\sqrt{3}}{2}$.
			\itemch $\cot\alpha=\cot\left(\dfrac{\pi}{3}+k2\pi\right)=\cot\left(\dfrac{\pi}{3}\right)=\dfrac{\sqrt{3}}{3}$.
		\end{itemchoice}

\begin{itemchoice}
			\itemch Ta có $\sin x=-\dfrac{1}{2}\Leftrightarrow\sin x=\sin(-\dfrac{\pi}{6})$.
			\itemch $\sin x=-\dfrac{1}{2}\Leftrightarrow\left[ \begin{array}{l}
x=-\dfrac{\pi}{6}+k2\pi\\x=\dfrac{7\pi}{6}+k2\pi
\end{array} \right.$ ($k\in\mathbb{Z}$).
			\itemch
			\begin{itemize}
				\item Trường hợp $1$: $x=-\dfrac{\pi}{6}+k2\pi$ ($k\in\mathbb{Z}$).\\
				Với $x\in(-\pi;\pi)$ ta có
				\begin{eqnarray*}
					&&-\pi <-\dfrac{\pi}{6}+k2\pi < \pi\quad(k\in\mathbb{Z})\\
					&\Leftrightarrow&-\dfrac{5\pi}{6} < k2\pi < \dfrac{7\pi}{6}\quad(k\in\mathbb{Z})\\
					&\Leftrightarrow&-\dfrac{5}{12} < k < \dfrac{7}{12}\quad(k\in\mathbb{Z})\\
					&\Rightarrow& k=0.
				\end{eqnarray*}
				\item Trường hợp $2$: $x=\dfrac{7\pi}{6}+k2\pi$ ($k\in\mathbb{Z}$).\\
				Với $x\in(-\pi;\pi)$ ta có
				\begin{eqnarray*}
					&&-\pi < \dfrac{7\pi}{6}+k2\pi < \pi\quad(k\in\mathbb{Z})\\
					&\Leftrightarrow&-\dfrac{13\pi}{6} < k2\pi <-\dfrac{\pi}{6}\quad(k\in\mathbb{Z})\\
					&\Leftrightarrow&-\dfrac{13}{12} < k <-\dfrac{1}{12}\quad(k\in\mathbb{Z})\\
					&\Rightarrow& k=-1.
				\end{eqnarray*}
			\end{itemize}
			Vậy trong khoảng $(-\pi;\pi)$ phương trình $\sin x=-\dfrac{1}{2}$ có 2 nghiệm.
			\itemch $\sin x=-\dfrac{1}{2}\Leftrightarrow\left[ \begin{array}{l}
x=-\dfrac{\pi}{6}+k2\pi\\x=\dfrac{7\pi}{6}+k2\pi
\end{array} \right.$\,($k\in\mathbb{Z}$).
			\begin{itemize}
				\item Trường hợp $1$: $x=-\dfrac{\pi}{6}+k2\pi$, ($k\in\mathbb{Z}$).\\
				Nghiệm âm lớn nhất là $x=-\dfrac{\pi}{6}$.
				\item Trường hợp $2$: $x=\dfrac{7\pi}{6}+k2\pi$, ($k\in\mathbb{Z}$).\\
				Nghiệm âm lớn nhất là $x=-\dfrac{5\pi}{6}$.
			\end{itemize}
			Do đó nghiệm âm lớn nhất của phương trình là $x=-\dfrac{\pi}{6}$.
		\end{itemchoice}

Theo đề $v_0 = 10$; $d = 5$ nên ta có phương trình
		\allowdisplaybreaks
		\begin{eqnarray*}
			5 = \dfrac{10^2 \sin 2\alpha}{10} &\Leftrightarrow& 5 = \dfrac{100 \sin 2\alpha}{10} \Leftrightarrow 5 = 10 \sin 2\alpha \Leftrightarrow \sin 2\alpha = \dfrac{1}{2}\\
			&\Leftrightarrow& \left[ \begin{array}{l}
2\alpha = 30^\circ + k360^\circ \\ 2\alpha = 150^\circ + k360^\circ
\end{array} \right. \Leftrightarrow \left[ \begin{array}{l}
\alpha = 15^\circ + k180^\circ \\ \alpha = 75^\circ + k180^\circ.
\end{array} \right.
		\end{eqnarray*}
		Do $0^\circ < \alpha < 90^\circ$ nên có hai góc ném là $\alpha_1 = 75^\circ$ và $\alpha_2 = 15^\circ$.\\
		Vậy $\alpha_1 - \alpha_2 = 75^\circ - 15^\circ = 60^\circ$.
